import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { Asignacion } from '../entities/asignacion.entity';
import { Planta } from '../../plantas/entities/planta.entity';
import { Jardinero } from '../../jardineros/entities/jardinero.entity';

@Injectable()
export class AsignarJardineroRepository {
  constructor(
    @InjectRepository(Asignacion) private readonly asignaciones: Repository<Asignacion>,
    @InjectRepository(Planta) private readonly plantas: Repository<Planta>,
    @InjectRepository(Jardinero) private readonly jardineros: Repository<Jardinero>
  ) {}

  buscarPlantaRepository(plantaId: number) {
    return this.plantas.findOneBy({ id: plantaId });
  }

  buscarJardineroRepository(jardineroId: number) {
    return this.jardineros.findOneBy({ id: jardineroId });
  }

  async asignarJardineroRepository(plantaId: number, jardineroId: number, rol: string) {
    const asignacion = { plantaId, jardineroId, rol };
    await this.asignaciones.insert(asignacion);
    return asignacion;
  }
}

import { ConflictException, Injectable, NotFoundException } from '@nestjs/common';
import { QueryFailedError } from 'typeorm';
import { AsignarJardineroRepository } from './repository';

@Injectable()
export class AsignarJardineroService {
  constructor(private readonly repository: AsignarJardineroRepository) {}

  async asignarJardineroService(plantaId: number, jardineroId: number, rol: string) {
    const planta = await this.repository.buscarPlantaRepository(plantaId);
    const jardinero = await this.repository.buscarJardineroRepository(jardineroId);
    if (!planta || !jardinero) {
      throw new NotFoundException('No existe la planta o el jardinero');
    }

    try {
      return await this.repository.asignarJardineroRepository(plantaId, jardineroId, rol);
    } catch (error) {
      if (error instanceof QueryFailedError && error.driverError.code === '23505') {
        throw new ConflictException('El jardinero ya está asignado a esa planta');
      }
      throw error;
    }
  }
}

