export class ReferenciaInexistenteError extends Error {}

export async function asignarJardineroService(plantaId, jardineroId, rol) {
  const planta = await buscarPlantaRepository(plantaId);
  const jardinero = await buscarJardineroRepository(jardineroId);
  if (!planta || !jardinero) {
    throw new ReferenciaInexistenteError('No existe la planta o el jardinero');
  }
  return asignarJardineroRepository(plantaId, jardineroId, rol);
}

import { asignarJardineroService, ReferenciaInexistenteError } from './service.mjs';

export async function handler(event) {
  const plantaId = Number(event.pathParameters.plantaId);
  const { jardineroId, rol } = JSON.parse(event.body);
  try {
    const asignacion = await asignarJardineroService(plantaId, jardineroId, rol);
    return { statusCode: 201, body: JSON.stringify(asignacion) };
  } catch (error) {
    if (error instanceof ReferenciaInexistenteError) {
      return { statusCode: 404, body: JSON.stringify({ message: error.message }) };
    }
    if (error.name === 'ConditionalCheckFailedException') {
      return { statusCode: 409, body: JSON.stringify({ message: 'El jardinero ya está asignado a esa planta' }) };
    }
    throw error;
  }
}

